/**
 *
 * AutoCompletePopup is the popup container that wraps the dropdown content inside the positioner.
 *
 * [Live Demo](https://www.primereact.org/autocomplete/)
 *
 * @module AutoCompletePopup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseMotionProps } from '@primereact/types/headless/motion';
import type { AutoCompleteRootInstance } from './AutoCompleteRoot.types';
/**
 * Defines passthrough(pt) options type in AutoCompletePopup component.
 */
export type AutoCompletePopupPassThroughType<E> = PassThroughType<AutoCompletePopupInstance, E>;
/**
 * Defines passthrough(pt) options of AutoCompletePopup component.
 */
export interface AutoCompletePopupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: AutoCompletePopupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in AutoCompletePopup component.
 */
export interface AutoCompletePopupProps extends BaseComponentProps<AutoCompletePopupInstance, unknown, AutoCompletePopupPassThrough> {
    /**
     * Used to apply motion to the popup element. It accepts the same properties as useMotion hook.
     */
    motionProps?: UseMotionProps | undefined;
}
/**
 * Defines valid state in AutoCompletePopup component.
 */
export interface AutoCompletePopupState {
}
/**
 * Defines the methods and properties exposed by AutoCompletePopup component.
 */
export interface AutoCompletePopupExposes {
    /**
     * The AutoComplete component instance.
     */
    autocomplete: AutoCompleteRootInstance | undefined | null;
}
/**
 * Instance of AutoCompletePopup component.
 */
export type AutoCompletePopupInstance = ComponentInstance<AutoCompletePopupProps, AutoCompletePopupState, AutoCompletePopupExposes>;
